<?php
// PUBLIC read endpoint. Drop-in replacement for the static data.js: on the hosted site,
// change  <script src="data.js"></script>  to  <script src="php/data.php"></script>
// and the display timer becomes live (records expire the moment show_until passes, with
// no rebuild). GEO + REPS stay static (regenerated by build_site.py -> data/geo.json,
// data/reps.json); only the activity list is queried live.

require __DIR__ . '/../includes/activities.php';
pdo();
header('Content-Type: application/javascript; charset=utf-8');

$geo  = @file_get_contents(__DIR__ . '/../data/geo.json');
$reps = @file_get_contents(__DIR__ . '/../data/reps.json');
if ($geo === false)  { $geo  = '{}'; }
if ($reps === false) { $reps = '{}'; }

$act = array_map(function ($r) {
    foreach (['us_house', 'il_senate', 'il_house'] as $k) {
        $r[$k] = json_decode($r[$k] ?: '[]');   // JSON text -> int array, as the front end expects
    }
    // PostgreSQL hands back real booleans; the front end gets true/false either way.
    foreach (['featured', 'confirm', 'historic'] as $k) {
        $r[$k] = in_array($r[$k] ?? false, [true, 1, '1', 't', 'true'], true);
    }
    if ($r['latitude']  !== null) { $r['latitude']  = (float) $r['latitude']; }
    if ($r['longitude'] !== null) { $r['longitude'] = (float) $r['longitude']; }
    unset($r['version']);   // the database's edit counter, not part of a record
    return $r;
}, fresh_activities());

echo 'window.GEO=' . $geo . ';window.REPS=' . $reps . ';window.ACT=' . json_encode($act) . ';';
